const std = @import("std");
const evm = @import("evm");
const primitives = @import("voltaire");

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var db = evm.Database.init(allocator);
    defer db.deinit();

    const code = [_]u8{ 0x60, 0x2a, 0x60, 0x00, 0x52, 0x60, 0x20, 0x60, 0x00, 0xf3 };
    const target = try primitives.Address.fromHex(
        "0x2000000000000000000000000000000000000002",
    );
    try db.set_code(target.bytes, &code);

    var instance = try evm.MainnetEvm.init(allocator, &db, .{}, .{}, 0, null);
    defer instance.deinit();
    const res = instance.call(.{ .call = .{
        .caller = @splat(0),
        .to = target.bytes,
        .value = 0,
        .input = &.{},
        .gas = 100_000,
    } });
    std.debug.print("success={} output={x}\n", .{ res.success, res.output });
}
